using System; using System.IO; using System.IO.Ports; using System.Linq; using System.Text.Json; using System.Windows; using Microsoft.Win32; namespace ConsoleUARTPro; public partial class MainWindow : Window { SerialPort? serial; readonly string settings=Path.Combine(Environment.GetFolderPath(Environment.SpecialFolder.LocalApplicationData),"ConsoleUARTPro","settings.json"); public MainWindow(){InitializeComponent(); Refresh_Click(this,new RoutedEventArgs()); LoadPrefs(); Closed+=(_,_)=>{serial?.Close();serial?.Dispose();};} void Refresh_Click(object sender,RoutedEventArgs e){Ports.ItemsSource=SerialPort.GetPortNames().OrderBy(x=>x).ToArray();Ports.SelectedIndex=Ports.Items.Count>0?0:-1;} void Connect_Click(object sender,RoutedEventArgs e){if(Ports.SelectedItem is not string port){Status.Text="Select a serial port.";return;} try {serial?.Dispose();int baud=int.Parse(((System.Windows.Controls.ComboBoxItem)Bauds.SelectedItem).Content.ToString()!);serial=new SerialPort(port,baud){ReadTimeout=500,Handshake=Handshake.None,DtrEnable=false,RtsEnable=false};serial.DataReceived+=Received;serial.Open();Status.Text="Connected to "+port+" (RX-only software; verify hardware adapter safety).";}catch(Exception ex){Status.Text=ex.Message;}} void Received(object sender,SerialDataReceivedEventArgs e){try{string data=serial?.ReadExisting()??"";Dispatcher.BeginInvoke(()=>{Log.AppendText(data);Log.ScrollToEnd();});}catch(Exception){}} void Disconnect_Click(object sender,RoutedEventArgs e){serial?.Close();Status.Text="Disconnected";} void Save_Click(object sender,RoutedEventArgs e){var dialog=new SaveFileDialog{Filter="Text log|*.txt",FileName="uart-log.txt"};if(dialog.ShowDialog()==true)File.WriteAllText(dialog.FileName,Log.Text);} void Save_ClickPrefs(object sender,RoutedEventArgs e){var data=new Prefs(UpdateMode.SelectedIndex,Database.IsChecked==true,Pico.IsChecked==true,Esp.IsChecked==true,Pi.IsChecked==true,Boardview.IsChecked==true,Thermal.IsChecked==true,Logic.IsChecked==true);Directory.CreateDirectory(Path.GetDirectoryName(settings)!);File.WriteAllText(settings,JsonSerializer.Serialize(data));PrefsStatus.Text="Preferences saved. No software was downloaded or installed.";} void LoadPrefs(){try{var p=JsonSerializer.Deserialize<Prefs>(File.ReadAllText(settings));if(p==null)return;UpdateMode.SelectedIndex=Math.Clamp(p.Mode,0,2);Database.IsChecked=p.Database;Pico.IsChecked=p.Pico;Esp.IsChecked=p.Esp;Pi.IsChecked=p.Pi;Boardview.IsChecked=p.Boardview;Thermal.IsChecked=p.Thermal;Logic.IsChecked=p.Logic;}catch(IOException){}catch(JsonException){}} record Prefs(int Mode,bool Database,bool Pico,bool Esp,bool Pi,bool Boardview,bool Thermal,bool Logic); }